        event_edge = clk_b ? EDGE_RISING : EDGE_FALLING;
        if (
            ((event_edge == EDGE_RISING) && ((edge_interest[SIGNAL_CLKB] & 1) != 0)) ||
            ((event_edge == EDGE_FALLING) && ((edge_interest[SIGNAL_CLKB] & 2) != 0)) ||
            ((event_edge == EDGE_RISING) &&
             1'b0 &&
             (timer_deadline == NO_TIMER))) begin
          run_step(PHASE_EDGE, SIGNAL_CLKB,
                   event_edge, requests);
          service_requests(requests);
        end
      end
    end
  endtask

  task automatic observe_clock_2();
    int requests;
    int event_edge;
    while (status == 0) begin
      @(manual_clk);
`ifdef CPPTB_SV_DPI_TIMING
      note_time_step();
`endif
      event_edge = manual_clk ? EDGE_RISING : EDGE_FALLING;
      if (
          ((event_edge == EDGE_RISING) && ((edge_interest[SIGNAL_MANUALCLK] & 1) != 0)) ||
          ((event_edge == EDGE_FALLING) && ((edge_interest[SIGNAL_MANUALCLK] & 2) != 0)) ||
          ((event_edge == EDGE_RISING) &&
           1'b0 &&
           (timer_deadline == NO_TIMER))) begin
        if (status == 0) begin
          run_step(PHASE_EDGE, SIGNAL_MANUALCLK,
                   event_edge, requests);
          service_requests(requests);
`ifdef CPPTB_SV_DPI_CALENDAR_TIMING
          calendar_drain_phases();
`endif
        end
      end
    end
  endtask

  task automatic observe_clock_3();
    int requests;
    int event_edge;
    while (status == 0) begin
      @(derived_clk);
`ifdef CPPTB_SV_DPI_TIMING
      note_time_step();
`endif
      event_edge = derived_clk ? EDGE_RISING : EDGE_FALLING;
      if (
          ((event_edge == EDGE_RISING) && ((edge_interest[SIGNAL_DERIVEDCLK] & 1) != 0)) ||
          ((event_edge == EDGE_FALLING) && ((edge_interest[SIGNAL_DERIVEDCLK] & 2) != 0)) ||
          ((event_edge == EDGE_RISING) &&
           1'b0 &&
           (timer_deadline == NO_TIMER))) begin
        if (status == 0) begin
          run_step(PHASE_EDGE, SIGNAL_DERIVEDCLK,
                   event_edge, requests);
          service_requests(requests);
`ifdef CPPTB_SV_DPI_CALENDAR_TIMING
          calendar_drain_phases();
`endif
        end
      end
    end
  endtask

  task automatic observe_signal_0();
    int requests;
    int event_edge;
    while (status == 0) begin
      @(event_observed);
`ifdef CPPTB_SV_DPI_TIMING
      note_time_step();
`endif
      if (status == 0) begin
        event_edge = event_observed ? EDGE_RISING : EDGE_FALLING;
        if (
            ((event_edge == EDGE_RISING) && ((edge_interest[SIGNAL_EVENTOBSERVED] & 1) != 0)) ||
            ((event_edge == EDGE_FALLING) && ((edge_interest[SIGNAL_EVENTOBSERVED] & 2) != 0))) begin
          run_step(PHASE_EDGE, SIGNAL_EVENTOBSERVED, event_edge, requests);
          service_requests(requests);
`ifdef CPPTB_SV_DPI_CALENDAR_TIMING
          calendar_drain_phases();
`endif
        end
      end
    end
  endtask

  initial begin
    clk_a = 1'b0;
    clk_b = 1'b0;
    rst_n = '0;
    manual_clk = '0;
    derived_gate = '0;
    stable_signal = '0;
    predicate_signal = '0;
    event_drive = '0;
    force_net_source = '0;
    drive_value = '0;
    addend = '0;
    packed65_i = '0;
    packed137_i = '0;
    array73_i = '{default: '0};
    matrix65_i = '{default: '0};
    sim_cycles = 0;
    timer_generation = 0;
    timer_deadline = NO_TIMER;
    timer_owner_target = NO_TIMER;
    iterations = 1;
    status = 0;
    track_falling_edges = 1'b0;
    clock_drivers_active = 1'b0;
`ifdef CPPTB_SV_DPI_TIMING
    phase_requests = 0;
    phase_barrier_token = 1'b0;
    last_started_time = $time;
`endif
    void'($value$plusargs("CPPTB_CONFORMANCE_ITERS=%d", iterations));

    for (int i = 0; i < INPUT_WORD_COUNT; i++) begin
      in_words[i] = '0;
    end
    for (int i = 0; i < OUTPUT_WORD_COUNT; i++) begin
      out_words[i] = '0;
    end
    for (int i = 0; i < CPPTB_SIGNAL_COUNT; i++) begin
      edge_interest[i] = '0;
      registered_clock[i] = 1'b0;
      primary_clock[i] = 1'b0;
    end

    cpptb_dpi_init(iterations, TIMEPRECISION_FS);
`ifdef CPPTB_ENABLE_SV_LOGGING
    cpptb_log_pkg::configure();
`endif
`ifdef CPPTB_SV_DPI_CALENDAR_TIMING
    calendar_initialize();
`endif
    run_step(PHASE_INIT, NO_SIGNAL, EDGE_RISING, initial_requests);
    service_requests(initial_requests);
    clock_drivers_active = 1'b1;
    if (status == 0) begin
      fork
`ifdef CPPTB_SV_DPI_CALENDAR_TIMING
        calendar_owner();
`else
        timer_owner();
`ifdef CPPTB_SV_DPI_TIMING
        phase_pump();
`endif
        drive_clock_0();
        drive_clock_1();
`endif
        observe_clock_2();
        observe_clock_3();
        observe_signal_0();
      join_none
    end

    wait (status != 0);
    timer_generation++;
    if (status < 0) begin
      $fatal(1, "scheduler_conformance DPI testbench failed");
    end
    $finish;
  end

  scheduler_conformance i_dut (
      .rst_n(rst_n),
      .clk_a(clk_a),
      .clk_b(clk_b),
      .manual_clk(manual_clk),
      .derived_gate(derived_gate),
      .stable_signal(stable_signal),
      .predicate_signal(predicate_signal),
      .event_drive(event_drive),
      .force_net_source(force_net_source),
      .drive_value(drive_value),
      .addend(addend),
      .packed65_i(packed65_i),
      .packed65_o(packed65_o),
      .packed137_i(packed137_i),
      .packed137_o(packed137_o),
      .array73_i(array73_i),
      .array73_o(array73_o),
      .matrix65_i(matrix65_i),
      .matrix65_o(matrix65_o),
      .derived_clk(derived_clk),
      .event_observed(event_observed),
      .comb_sum(comb_sum),
      .sampled_a(sampled_a),
      .sampled_b(sampled_b),
      .sampled_manual(sampled_manual),
      .sampled_derived(sampled_derived),
      .count_a(count_a),
      .count_b(count_b),
      .count_manual(count_manual),
      .count_derived(count_derived),
      .internal_comb_fanout(internal_comb_fanout),
      .internal_clocked_fanout(internal_clocked_fanout),
      .internal_net_fanout(internal_net_fanout)
  );

